WITH x9 AS (SELECT X(x6.RTRIM('*s*')) FROM x10 GROUP BY x6.RTRIM('*s*') ORDER BY CASE WHEN x6.RTRIM('*s*') IS NULL THEN 1 ELSE 0 END, x6.RTRIM('*s*')) SELECT x6.RTRIM('*s*'), x6.RTRIM('*s*'), MIN(x6.RTRIM('*s*') + 0) > 19980501000000 AS x4, x6.RTRIM('*s*') FROM v42880 AS x6 WHERE CURRENT_TIME(6) = x6.RTRIM('*s*')